using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage("🏆 No egg data yet! Start earning eggs by chatting! 🥚");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        if (data["users"] == null || !data["users"].HasValues) {
            CPH.SendMessage("🏆 No egg data yet! Start earning eggs by chatting! 🥚");
            return false;
        }

        // Build leaderboard
        var userList = new List<Tuple<string, int>>();

        foreach (var user in data["users"]) {
            string userId = user.Key;
            int eggs = (int)(user.Value["eggs"] ?? 0);

            // Try to get username from Streamer.bot API or use userId as fallback
            string userName = userId;
            try {
                var userInfo = CPH.TwitchGetUser(userId);
                if (userInfo != null) {
                    userName = userInfo.UserLogin;
                }
            } catch {
                // Use userId if username lookup fails
            }

            userList.Add(new Tuple<string, int>(userName, eggs));
        }

        // Sort by eggs descending and take top 10
        var topUsers = userList.OrderByDescending(u => u.Item2).Take(10).ToList();

        if (topUsers.Count == 0) {
            CPH.SendMessage("🏆 No egg data yet! Start earning eggs by chatting! 🥚");
            return false;
        }

        // Build message
        string message = "🏆 Top Egg Holders: ";
        for (int i = 0; i < topUsers.Count; i++) {
            if (i > 0) message += " | ";
            message += $"{i + 1}. {topUsers[i].Item1} ({topUsers[i].Item2} 🥚)";
        }

        CPH.SendMessage(message);
        return true;
    }
}
